   110  UA_String_equal(const UA_String *s1, const UA_String *s2) {
   111      if(s1->length != s2->length)
   112          return false;
   113      i32 is = memcmp((char const*)s1->data,
   114                      (char const*)s2->data, s1->length);
   115      return (is == 0) ? true : false;
